package vn.svframe.svframelib.api.crafting.uimanager;
import vn.svframe.svframelib.api.crafting.uifilters.UIFilter; import vn.svframe.svframelib.api.util.ui.*; import net.minecraft.item.ItemStack; import java.util.*;
public class ProvidedUIFilter implements Comparable<ProvidedUIFilter>,Cloneable { private UIFilter parent; private String argument,data; private QuickNumberRange amountRange; public ProvidedUIFilter(UIFilter p,String a,String d){this(p,a,d,new QuickNumberRange(1));} public ProvidedUIFilter(UIFilter p,String a,String d,int amount){this(p,a,d,new QuickNumberRange(amount));} public ProvidedUIFilter(UIFilter p,String a,String d,QuickNumberRange range){parent=Objects.requireNonNull(p);argument=a==null?"":a;data=d==null?"":d;amountRange=range==null?new QuickNumberRange(1):range;} public static ProvidedUIFilter getFromString(String s,FriendlyFeedbackProvider f){return UIFilterManager.getUIFilter(s,f);} public boolean isAir(){return "air".equalsIgnoreCase(argument)||"minecraft:air".equalsIgnoreCase(argument);} public boolean matches(ItemStack stack,boolean checkAmount,FriendlyFeedbackProvider f){return (!checkAmount||checkAmount(stack==null?0:stack.getCount()))&&parent.matches(stack,argument,data,f);} public boolean isValid(FriendlyFeedbackProvider f){return parent.isValid(argument,data,f);} public ItemStack getItemStack(FriendlyFeedbackProvider f){ItemStack s=parent.getItemStack(argument,data,f);if(!s.isEmpty()&&hasAmount())s.setCount(getAmount());return s;} public ItemStack getDisplayStack(FriendlyFeedbackProvider f){return parent.getDisplayStack(argument,data,f);} public ArrayList<String> getDescription(){return parent.getDescription(argument,data);} public UIFilter getParent(){return parent;} public void setParent(UIFilter p){parent=p;} public String getArgument(){return argument;} public void setArgument(String s){argument=s==null?"":s;} public String getData(){return data;} public void setData(String s){data=s==null?"":s;} public QuickNumberRange getAmountRange(){return amountRange;} public void setAmountRange(QuickNumberRange r){amountRange=r;} public Integer getAmount(){return (int)Math.round(amountRange.getMin());} public int getAmount(int fallback){return hasAmount()?getAmount():fallback;} public void setAmount(Integer a){amountRange=new QuickNumberRange(a==null?1:a);} public boolean hasAmount(){return amountRange!=null;} public boolean checkAmount(double a){return amountRange==null||amountRange.inRange(a);} public static boolean checkAmount(QuickNumberRange r,double a){return r==null||r.inRange(a);} public int compareTo(ProvidedUIFilter o){return toString().compareToIgnoreCase(o.toString());} public ProvidedUIFilter clone(){return new ProvidedUIFilter(parent,argument,data,amountRange);} public String toString(){return parent.getIdentifier()+":"+argument+(data.isBlank()?"":":"+data);} }
